/** the number (1..114) of a surah named in Arabic ("سورة" in front is ignored), or null */
export function surahNumberOfName(name) {
  const f = fold(name).replace(/^سوره?\s+/, '');
  return BY_NAME.get(f) || BY_NAME.get(f.replace(/^ال/, '')) || null;
}
/** the name of surah `num` in `lang`, or null when that language has no list (the caller keeps the Arabic name) */
export function surahNameIn(lang, num) { const l = LISTS[lang]; return l && num >= 1 && num <= 114 ? l[num - 1] : null; }
